  getUploadedFiles(key) {
    var bucketName = "renewalapplicationemis";
    var filename = key;
    let expiry: number = 1800;
    this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe((result) => {
      if (result) {        
        return result.url        
      }
      else {
        this.alertService.error('Error in Uploading File please try again');
      }
    });
  }  
  numericOnly(event): boolean {    
    let pattern = /^([0-9])$/;
    let result = pattern.test(event.data);    
    if(result ==true){
      return event; 
    }else{                               
      event.target.value = event.target.value.slice(0, -1);
    }    
 }  
  openCamera(answer, question, answerIndex, questionIndex) {
    const options: CameraOptions = {
      quality: 100,
      targetWidth: 900,
      targetHeight: 600,
      destinationType: this.camera.DestinationType.FILE_URI,
      sourceType: this.camera.PictureSourceType.CAMERA,
      encodingType: this.camera.EncodingType.JPEG,
      mediaType: this.camera.MediaType.PICTURE,
    };        
    this.camera.getPicture(options).then(
      (imageData) => {
        {
          this.file.resolveLocalFilesystemUrl(imageData).then(async(entry: FileEntry) => {
            entry.file(file => {              
              var fileName = file.name;
              this.docfile = file;
              var splittedName = fileName.split(".");
              const fileReader: FileReader = new FileReader();
              fileReader.readAsDataURL(file);
              fileReader.onload = async(event: Event) => {
                this.uploadUrl = fileReader.result;
                var bucketName = "renewalapplicationemis";
                var filename = splittedName[0];
                var ext = splittedName[1];
                let expiry: number = 300;
                await this.uploadService.getSignedUrl(bucketName, ext, filename, expiry).subscribe(async(result) => {
                  if (result) {                                      
                    let file: File = this.docfile;
                    await this.uploadService.uploadFile(result.url, file).subscribe(async(res) => {                      
                      await this.uploadService.getUploadedFiles(bucketName, file, expiry).subscribe(async (urlresult) => {
                        if (urlresult) {                         
                          this.imageData = result.key;                                                    
                          let questionInfo = {
                            answer: this.imageData,
                            question: question,
                            answerIndex: answerIndex,
                            questionIndex: questionIndex,
                          };
                          this.valueChange.emit(questionInfo);                          
                        }
                        else {
                          this.alertService.error('Error in Uploading File please try again');
                        }
                      });                      
                  });                  
              this.alertService.success('File Uploaded Successfully');
            }
          })
        }              
            });
          });
        }
      },
      (err) => {        
        alert("error " + JSON.stringify(err));
      }
    );
  }

  readFile(file: any) {
    const reader = new FileReader();
    reader.onloadend = () => {
      const imgBlob = new Blob([reader.result], {
        type: file.type
      });
      const formData = new FormData();      
    };
    reader.readAsArrayBuffer(file);
  }

  getQuestion(question, id) {
    if (question.selectedAnswer.length) {
      let selectedAnswerIds = question.selectedAnswer.map((el) => {
        return el.answer_id;
      });
      let found = selectedAnswerIds.includes(id);
      return found;
    } else {
      return false;
    }
  }
